CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'prof_avanzado',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS clients(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name))>0),ruc TEXT,phone TEXT,email TEXT,birth_date DATE,notes TEXT,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS professionals(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,color TEXT NOT NULL DEFAULT '#a67fd4');
CREATE TABLE IF NOT EXISTS services(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('Damas','Caballero','Faciales')),price BIGINT CHECK(price>=0),commission BIGINT CHECK(commission>=0),duration_minutes INTEGER NOT NULL DEFAULT 60 CHECK(duration_minutes>0),UNIQUE(name,category));
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL DEFAULT '',stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),minimum INTEGER NOT NULL DEFAULT 0 CHECK(minimum>=0),price BIGINT NOT NULL DEFAULT 0 CHECK(price>=0),commission_percent NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK(commission_percent BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS package_templates(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,service_id BIGINT NOT NULL REFERENCES services(id),sessions INTEGER NOT NULL CHECK(sessions>0),price BIGINT NOT NULL CHECK(price>=0),active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS client_packages(id BIGSERIAL PRIMARY KEY,client_id BIGINT NOT NULL REFERENCES clients(id),template_id BIGINT NOT NULL REFERENCES package_templates(id),total BIGINT NOT NULL CHECK(total>=0),paid BIGINT NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=total),sessions_total INTEGER NOT NULL CHECK(sessions_total>0),sessions_used INTEGER NOT NULL DEFAULT 0 CHECK(sessions_used>=0 AND sessions_used<=sessions_total),cancelled BOOLEAN NOT NULL DEFAULT false,notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appointments(id BIGSERIAL PRIMARY KEY,client_id BIGINT NOT NULL REFERENCES clients(id),professional_id BIGINT NOT NULL REFERENCES professionals(id),service_id BIGINT NOT NULL REFERENCES services(id),package_id BIGINT REFERENCES client_packages(id),date DATE NOT NULL,time TIME NOT NULL,status TEXT NOT NULL DEFAULT 'pendiente' CHECK(status IN ('pendiente','confirmada','completada','cancelada')),price BIGINT NOT NULL CHECK(price>=0),commission BIGINT NOT NULL DEFAULT 0 CHECK(commission>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS appointment_slot ON appointments(professional_id,date,time) WHERE status <> 'cancelada';
CREATE INDEX IF NOT EXISTS appointments_date_idx ON appointments(date);
CREATE TABLE IF NOT EXISTS payment_methods(id TEXT PRIMARY KEY,name TEXT NOT NULL,fee_percent NUMERIC(6,3) NOT NULL DEFAULT 0 CHECK(fee_percent BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS movements(id BIGSERIAL PRIMARY KEY,date DATE NOT NULL,type TEXT NOT NULL CHECK(type IN ('ingreso','egreso','servicio','venta_producto','paquete','apertura')),description TEXT NOT NULL DEFAULT '',method TEXT NOT NULL REFERENCES payment_methods(id),gross BIGINT NOT NULL CHECK(gross>=0),net BIGINT NOT NULL CHECK(net>=0),client_id BIGINT REFERENCES clients(id),professional_id BIGINT REFERENCES professionals(id),appointment_id BIGINT REFERENCES appointments(id),package_id BIGINT REFERENCES client_packages(id),product_id BIGINT REFERENCES products(id),quantity INTEGER CHECK(quantity>0),commission BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS movements_date_idx ON movements(date);
CREATE TABLE IF NOT EXISTS stock_movements(id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incidents(id BIGSERIAL PRIMARY KEY,appointment_id BIGINT NOT NULL REFERENCES appointments(id),description TEXT NOT NULL CHECK(length(trim(description))>0),user_id BIGINT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'abierta',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS source_client_name TEXT;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS source_payment TEXT;
ALTER TABLE appointments ALTER COLUMN client_id DROP NOT NULL;
ALTER TABLE appointments ALTER COLUMN commission DROP NOT NULL;
ALTER TABLE appointments ALTER COLUMN commission DROP DEFAULT;
CREATE TABLE IF NOT EXISTS import_batches(name TEXT PRIMARY KEY,imported_at TIMESTAMPTZ NOT NULL DEFAULT now());
